package app.asechka.android;

import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;

final class LiveLocationCard {
  static final int PERMISSION=2402;
  final MainActivity activity;final ApiClient api;final Ui u;
  final Handler main=new Handler(Looper.getMainLooper());final ExecutorService io=Executors.newSingleThreadExecutor();
  LinearLayout root;TextView statuses,partnerStatus;Button toggle;WebView map,expandedMap;android.app.Dialog expanded;JSONObject snapshot;boolean closed,busy;
  LiveLocationCard(MainActivity activity,ApiClient api){this.activity=activity;this.api=api;u=new Ui(activity);}
  LinearLayout view(){root=u.column();root.setBackground(u.shape(android.graphics.Color.WHITE,18));root.setClipToOutline(true);
    LinearLayout heading=u.row(8);heading.setPadding(u.dp(12),0,u.dp(6),0);TextView mapTitle=u.title("Find each other",13);Glyph.leading(mapTitle,"location",Ui.INK,15,6);heading.addView(mapTitle,new LinearLayout.LayoutParams(0,-2,1));toggle=u.textButton(enabled()?"Stop":"Share",()->{if(enabled())stop();else explain();});toggle.setTextSize(12);toggle.setTextColor(Ui.INK);heading.addView(toggle,new LinearLayout.LayoutParams(-2,u.dp(44)));root.addView(heading);
    map=map();FrameLayout mapFrame=new FrameLayout(activity);mapFrame.addView(map,new FrameLayout.LayoutParams(-1,-1));
    ImageView enlarge=Glyph.view(activity,"expand",Ui.INK);enlarge.setPadding(u.dp(12),u.dp(12),u.dp(12),u.dp(12));enlarge.setBackground(u.shape(0xf2ffffff,100));enlarge.setContentDescription("Expand map");enlarge.setOnClickListener(v->expand());FrameLayout.LayoutParams ep=new FrameLayout.LayoutParams(u.dp(44),u.dp(44),Gravity.TOP|Gravity.RIGHT);ep.setMargins(0,u.dp(6),u.dp(6),0);mapFrame.addView(enlarge,ep);root.addView(mapFrame,new LinearLayout.LayoutParams(-1,u.dp(160)));LinearLayout footer=u.row(8);footer.setPadding(u.dp(12),u.dp(7),u.dp(12),u.dp(7));statuses=u.text("A · Not sharing",10,Ui.INK);partnerStatus=u.text("Y · Not sharing",10,Ui.INK);partnerStatus.setGravity(Gravity.RIGHT);footer.addView(statuses,new LinearLayout.LayoutParams(0,-2,1));footer.addView(partnerStatus,new LinearLayout.LayoutParams(0,-2,1));root.addView(footer);
    root.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){poll.run();}public void onViewDetachedFromWindow(View v){main.removeCallbacks(poll);}});return root;
  }
  WebView map(){WebView web=new WebView(activity);web.setBackgroundColor(Ui.BLUE);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setUserAgentString("Asechka-Android/2.6.0 (https://asechka-website.vercel.app)");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return true;}public void onPageFinished(WebView w,String url){renderMap(w);}});try{String html=new String(readAsset("map/index.html"),StandardCharsets.UTF_8).replace("/* LEAFLET */",new String(readAsset("map/leaflet.js"),StandardCharsets.UTF_8)).replace("/* LEAFLET_CSS */",new String(readAsset("map/leaflet.css"),StandardCharsets.UTF_8));web.loadDataWithBaseURL(ApiClient.SITE+"/",html,"text/html","UTF-8",null);}catch(Exception ignored){}return web;}
  byte[] readAsset(String name)throws Exception{try(java.io.InputStream in=activity.getAssets().open(name);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return out.toByteArray();}}
  boolean enabled(){JSONObject c=api.store.read("live-location-consent");return c!=null&&c.optBoolean("enabled");}
  final Runnable poll=new Runnable(){public void run(){if(closed)return;refresh();main.postDelayed(this,10_000);}};
  void refresh(){if(busy)return;busy=true;io.execute(()->{try{JSONObject c=api.store.read("live-location-consent");if(c!=null&&!c.optBoolean("enabled")){try{api.location(OfflineStore.json("action","stop","actor",c.getString("actor"),"token",c.getString("token")));api.store.remove("live-location-consent");}catch(ApiClient.ApiError e){if(e.status==409)api.store.remove("live-location-consent");}}JSONObject value=api.location(null);main.post(()->{if(!closed){snapshot=value;render();}});}catch(Exception ignored){}finally{main.post(()->busy=false);}});}
  void render(){toggle.setText(enabled()?"Stop":"Share");JSONArray people=snapshot.optJSONArray("people");StringBuilder text=new StringBuilder();for(int i=0;people!=null&&i<people.length();i++){JSONObject p=people.optJSONObject(i),point=p.optJSONObject("position");if(i>0)text.append("     ");text.append(p.optString("actor").equals("asnat")?"A · ":"Y · ");if(point==null)text.append(p.optBoolean("sharing")?"Waiting for GPS":"Not sharing");else{long age=Math.max(0,(System.currentTimeMillis()-point.optLong("capturedAt"))/1000);text.append(age<60?"Live · ±"+point.optInt("accuracy")+"m":age/60+"m ago · paused");}}String[] labels=text.toString().split("     ",2);statuses.setText(labels.length>0?labels[0]:"A · Not sharing");partnerStatus.setText(labels.length>1?labels[1]:"Y · Not sharing");renderMap(map);if(expandedMap!=null)renderMap(expandedMap);}
  void renderMap(WebView web){if(snapshot!=null)web.evaluateJavascript("window.showPeople && window.showPeople("+snapshot.optJSONArray("people")+")",null);}
  void expand(){
    if(expanded!=null&&expanded.isShowing())return;
    expanded=new android.app.Dialog(activity);LinearLayout body=u.column();body.setBackgroundColor(Ui.BG);
    LinearLayout bar=u.row();bar.setPadding(u.dp(20),u.dp(10),u.dp(12),u.dp(10));bar.addView(u.title("Find each other",17),new LinearLayout.LayoutParams(0,-2,1));bar.addView(u.textButton("Done",()->expanded.dismiss()));body.addView(bar);
    expandedMap=map();body.addView(expandedMap,new LinearLayout.LayoutParams(-1,0,1));expanded.setContentView(body);
    expanded.setOnDismissListener(d->{if(expandedMap!=null){expandedMap.stopLoading();expandedMap.destroy();expandedMap=null;}});expanded.show();expanded.getWindow().setLayout(-1,-1);expanded.getWindow().setBackgroundDrawableResource(android.R.color.transparent);
  }
  void explain(){new AlertDialog.Builder(activity).setTitle("Share your live location?").setMessage("Your partner can see your location on Home. Sharing stays on until you stop it, including when Asechka is in the background. Android shows an ongoing notification with Stop. You can stop here anytime.").setNegativeButton("Cancel",null).setPositiveButton("Share until I stop",(d,w)->request()).show();}
  void request(){if(activity.checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&activity.checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){if(Build.VERSION.SDK_INT>=33)activity.requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION,android.Manifest.permission.POST_NOTIFICATIONS},PERMISSION);else activity.requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},PERMISSION);return;}if(Build.VERSION.SDK_INT>=33&&activity.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)activity.requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},2403);start();}
  void permission(int[] grants){boolean granted=activity.checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||activity.checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;if(granted)start();else Toast.makeText(activity,"Location permission was declined.",Toast.LENGTH_LONG).show();}
  void start(){if(busy)return;busy=true;String actor=activity.getSharedPreferences("preferences",0).getString("person","asnat");io.execute(()->{try{JSONObject value=api.location(OfflineStore.json("action","start","actor",actor));api.store.write("live-location-consent",OfflineStore.json("actor",actor,"token",value.getString("token"),"enabled",true));main.post(()->{resumeService(activity,api);snapshot=value;render();});}catch(Exception e){main.post(()->Toast.makeText(activity,e.getMessage(),Toast.LENGTH_LONG).show());}finally{main.post(()->busy=false);}});}
  void stop(){try{JSONObject c=api.store.read("live-location-consent");if(c!=null){c.put("enabled",false);api.store.write("live-location-consent",c);}activity.startService(new Intent(activity,LiveLocationService.class).setAction(LiveLocationService.STOP));toggle.setText("Share");statuses.setText("Sharing stopped here · removing the shared pin…");}catch(Exception e){Toast.makeText(activity,e.getMessage(),Toast.LENGTH_LONG).show();}refresh();}
  static void resumeService(Activity activity,ApiClient api){JSONObject c=api.store.read("live-location-consent");if(c==null||!c.optBoolean("enabled"))return;try{Intent intent=new Intent(activity,LiveLocationService.class);if(Build.VERSION.SDK_INT>=26)activity.startForegroundService(intent);else activity.startService(intent);}catch(RuntimeException ignored){}}
  void close(){closed=true;if(expanded!=null)expanded.dismiss();main.removeCallbacksAndMessages(null);if(map!=null){map.stopLoading();map.destroy();}io.shutdown();}
}
